INSERT INTO `mod_configure` (`id`, `title`, `content`, `update_time`) VALUES (1,'基本配置','{\"app_name\":\"booking\",\"app_name2\":\"Expedia\",\"logo\":\"\\/uploads\\/2025\\/08\\/b63c38192e5110a1f5969c881e690152.png\",\"open_time\":\"11:00:00\",\"close_time\":\"22:59:59\",\"with_open_time\":\"00:00:00\",\"with_close_time\":\"23:59:59\",\"register_reward\":\"5\",\"login_binary\":\"0 \",\"back_comm_multiple\":\"2\",\"comm_reward_daili\":\"0.1\",\"comm_reward_0\":\"0.1\",\"comm_reward_1\":\"0.001\",\"comm_reward_2\":\"0.001\",\"comm_reward_3\":\"0.005\",\"comm_reward_4\":\"0.005\"}',1763364265),(2,'首页内容','{\"pop_en\":\"\\/uploads\\/2025\\/03\\/2c0aa227669eab95a46030b608528a94.png\",\"pop_zh\":\"\\/uploads\\/2025\\/03\\/939747dc418da218876efcbe81eeb0e3.png\",\"pop_he\":\"\\/uploads\\/2025\\/03\\/1cade4e0700aa8362b209e93981e68d6.png\",\"pop_ar\":\"\\/uploads\\/2025\\/03\\/2bda63367a117263926f2d7f024afda5.png\",\"pop_es\":\"\",\"pop_pt\":\"\",\"pop_nl\":\"\",\"pop_fr\":\"\",\"pop_de\":\"\",\"about_us_en\":\"<p><b>Booking.com is one of the world\'s largest online travel companies. In 2023, its total booking value exceeded $150 billion, capturing a leading market share of nearly 46% in the global online travel market . It is also one of the most-visited travel websites globally, supported by a strong data-driven culture that involves conducting numerous user experience tests daily to optimize services . In recent years, the company has actively embraced generative AI technologies, launching the AI Trip Planner, which allows users to receive personalized destination, accommodation, and itinerary suggestions through natural conversation . Booking.com also aims to enhance the customer experience as a shared goal, focusing on strengthening customers\' sense of self-worth&nbsp;<\\/b><\\/p>\",\"about_us_zh\":\"<p><b>Booking.com\\u662f\\u5168\\u7403\\u6700\\u5927\\u7684\\u7dda\\u4e0a\\u65c5\\u904a\\u516c\\u53f8\\u4e4b\\u4e00\\u3002 2023\\u5e74\\uff0c\\u5176\\u7e3d\\u9810\\u8a02\\u984d\\u8d85\\u904e1500\\u5104\\u7f8e\\u5143\\uff0c\\u5728\\u5168\\u7403\\u7dda\\u4e0a\\u65c5\\u904a\\u5e02\\u5834\\u4e2d\\u4f54\\u64da\\u4e86\\u8fd146%\\u7684\\u4efd\\u984d\\uff0c\\u8655\\u65bc\\u9818\\u5148\\u5730\\u4f4d \\u3002 Booking.com\\u662f\\u5168\\u7403\\u8a2a\\u554f\\u91cf\\u6700\\u5927\\u7684\\u65c5\\u904a\\u7db2\\u7ad9\\u4e4b\\u4e00\\uff0c\\u516c\\u53f8\\u64c1\\u6709\\u6975\\u5f37\\u7684\\u6578\\u64da\\u9a45\\u52d5\\u6587\\u5316\\uff0c\\u6bcf\\u5929\\u9032\\u884c\\u5927\\u91cf\\u7528\\u6236\\u9ad4\\u9a57\\u6e2c\\u8a66\\u4ee5\\u512a\\u5316\\u670d\\u52d9 \\u3002\\u8fd1\\u5e74\\u4f86\\uff0c\\u5b83\\u7a4d\\u6975\\u64c1\\u62b1\\u751f\\u6210\\u5f0fAI\\u6280\\u8853\\uff0c\\u63a8\\u51fa\\u4e86AI\\u65c5\\u884c\\u898f\\u5283\\u5668\\uff0c\\u7528\\u6236\\u53ef\\u4ee5\\u900f\\u904e\\u81ea\\u7136\\u5c0d\\u8a71\\u7372\\u5f97\\u500b\\u4eba\\u5316\\u7684\\u76ee\\u7684\\u5730\\u3001\\u4f4f\\u5bbf\\u548c\\u884c\\u7a0b\\u5efa\\u8b70 \\u3002 booking.com\\u4e5f\\u5c07\\u63d0\\u5347\\u9867\\u5ba2\\u9ad4\\u9a57\\u4f5c\\u70ba\\u4e00\\u9805\\u5171\\u540c\\u76ee\\u6a19\\uff0c\\u65e8\\u5728\\u589e\\u5f37\\u9867\\u5ba2\\u7684\\u81ea\\u6211\\u50f9\\u503c\\u611f\\u3002<\\/b><\\/p>\",\"about_us_he\":\"<p><span>Booking.com \\u05d4\\u05d9\\u05d0 \\u05d0\\u05d7\\u05ea \\u05de\\u05d7\\u05d1\\u05e8\\u05d5\\u05ea \\u05d4\\u05ea\\u05d9\\u05d9\\u05e8\\u05d5\\u05ea \\u05d4\\u05de\\u05e7\\u05d5\\u05d5\\u05e0\\u05d5\\u05ea \\u05d4\\u05d2\\u05d3\\u05d5\\u05dc\\u05d5\\u05ea \\u05d1\\u05e2\\u05d5\\u05dc\\u05dd. \\u05d1\\u05e9\\u05e0\\u05ea 2023, \\u05d4\\u05d9\\u05e7\\u05e3 \\u05d4\\u05d4\\u05d6\\u05de\\u05e0\\u05d5\\u05ea \\u05d4\\u05db\\u05d5\\u05dc\\u05dc \\u05e9\\u05dc\\u05d4 \\u05e2\\u05dc\\u05d4 \\u05e2\\u05dc 1.5 \\u05d8\\u05e8\\u05d9\\u05dc\\u05d9\\u05d5\\u05df \\u05d3\\u05d5\\u05dc\\u05e8, \\u05d5\\u05ea\\u05e4\\u05e1\\u05d4 \\u05e0\\u05ea\\u05d5\\u05df \\u05e9\\u05d5\\u05e7 \\u05e9\\u05dc \\u05db\\u05de\\u05e2\\u05d8 46% \\u05d1\\u05e9\\u05d5\\u05e7 \\u05d4\\u05ea\\u05d9\\u05d9\\u05e8\\u05d5\\u05ea \\u05d4\\u05de\\u05e7\\u05d5\\u05d5\\u05df \\u05d4\\u05e2\\u05d5\\u05dc\\u05de\\u05d9, \\u05de\\u05d4 \\u05e9\\u05de\\u05e6\\u05d9\\u05d1 \\u05d0\\u05d5\\u05ea\\u05d4 \\u05d1\\u05e2\\u05de\\u05d3\\u05d4 \\u05de\\u05d5\\u05d1\\u05d9\\u05dc\\u05d4&nbsp;<\\/span>. \\u05d4\\u05d0\\u05ea\\u05e8 \\u05e9\\u05dc Booking.com \\u05d4\\u05d5\\u05d0 \\u05d0\\u05d7\\u05d3 \\u05de\\u05d0\\u05ea\\u05e8\\u05d9 \\u05d4\\u05ea\\u05d9\\u05d9\\u05e8\\u05d5\\u05ea \\u05d4\\u05e0\\u05e6\\u05e4\\u05d9\\u05dd \\u05d1\\u05d9\\u05d5\\u05ea\\u05e8 globally, \\u05d5\\u05dc\\u05d7\\u05d1\\u05e8\\u05d4 \\u05d9\\u05e9 \\u05ea\\u05e8\\u05d1\\u05d5\\u05ea \\u05de\\u05d5\\u05e0\\u05e2\\u05ea-\\u05e0\\u05ea\\u05d5\\u05e0\\u05d9\\u05dd \\u05d7\\u05d6\\u05e7\\u05d4 \\u05de\\u05d0\\u05d5\\u05d3, \\u05d4\\u05de\\u05d1\\u05e6\\u05e2\\u05ea \\u05de\\u05d1\\u05d3\\u05d9\\u05e7\\u05d5\\u05ea \\u05d7\\u05d5\\u05d5\\u05d9\\u05ea \\u05de\\u05e9\\u05ea\\u05de\\u05e9 \\u05e8\\u05d1\\u05d5\\u05ea \\u05de\\u05d3\\u05d9 \\u05d9\\u05d5\\u05dd \\u05db\\u05d3\\u05d9 \\u05dc\\u05d9\\u05d9\\u05e2\\u05dc \\u05d0\\u05ea \\u05d4\\u05e9\\u05d9\\u05e8\\u05d5\\u05ea&nbsp;. \\u05d1\\u05e9\\u05e0\\u05d9\\u05dd \\u05d4\\u05d0\\u05d7\\u05e8\\u05d5\\u05e0\\u05d5\\u05ea, \\u05d4\\u05d9\\u05d0 \\u05d0\\u05d9\\u05de\\u05e6\\u05d4 \\u05d1\\u05d0\\u05d5\\u05e4\\u05df \\u05e4\\u05e2\\u05d9\\u05dc \\u05d8\\u05db\\u05e0\\u05d5\\u05dc\\u05d5\\u05d2\\u05d9\\u05d5\\u05ea \\u05d1\\u05d9\\u05e0\\u05d4 \\u05de\\u05dc\\u05d0\\u05db\\u05d5\\u05ea\\u05d9\\u05ea \\u05d9\\u05e6\\u05d9\\u05e8\\u05ea\\u05d9\\u05ea (Generative AI) \\u05d5\\u05d4\\u05e9\\u05d9\\u05e7\\u05d4 \\u05db\\u05dc\\u05d9 \\u05ea\\u05db\\u05e0\\u05d5\\u05df \\u05d8\\u05d9\\u05d5\\u05dc\\u05d9\\u05dd \\u05de\\u05d1\\u05d5\\u05e1\\u05e1 AI, \\u05d4\\u05de\\u05d0\\u05e4\\u05e9\\u05e8 \\u05dc\\u05de\\u05e9\\u05ea\\u05de\\u05e9\\u05d9\\u05dd \\u05dc\\u05e7\\u05d1\\u05dc \\u05d4\\u05de\\u05dc\\u05e6\\u05d5\\u05ea \\u05de\\u05d5\\u05ea\\u05d0\\u05de\\u05d5\\u05ea \\u05d0\\u05d9\\u05e9\\u05d9\\u05ea \\u05dc\\u05d9\\u05e2\\u05d3\\u05d9\\u05dd, \\u05de\\u05e7\\u05d5\\u05de\\u05d5\\u05ea \\u05dc\\u05d9\\u05e0\\u05d4 \\u05d5\\u05ea\\u05db\\u05e0\\u05d9\\u05d5\\u05ea itineraries \\u05d1\\u05d0\\u05de\\u05e6\\u05e2\\u05d5\\u05ea \\u05e9\\u05d9\\u05d7\\u05d4 \\u05d8\\u05d1\\u05e2\\u05d9\\u05ea&nbsp;. Booking.com \\u05d2\\u05dd \\u05d4\\u05e6\\u05d9\\u05d1\\u05d4 \\u05db\\u05de\\u05d8\\u05e8\\u05d4 \\u05de\\u05e9\\u05d5\\u05ea\\u05e4\\u05ea \\u05dc\\u05e9\\u05e4\\u05e8 \\u05d0\\u05ea \\u05d7\\u05d5\\u05d5\\u05d9\\u05ea \\u05d4\\u05dc\\u05e7\\u05d5\\u05d7, \\u05d1\\u05de\\u05d8\\u05e8\\u05d4 \\u05dc\\u05d4\\u05d2\\u05d1\\u05d9\\u05e8 \\u05d0\\u05ea \\u05ea\\u05d7\\u05d5\\u05e9\\u05ea \\u05d4\\u05e2\\u05e8\\u05da \\u05d4\\u05e2\\u05e6\\u05de\\u05d9 \\u05e9\\u05dc \\u05d4\\u05dc\\u05e7\\u05d5\\u05d7\\u05d5\\u05ea&nbsp;.<\\/p><p><\\/p>\",\"about_us_ar\":\"<p>Booking.com \\u0647\\u064a \\u0648\\u0627\\u062d\\u062f\\u0629 \\u0645\\u0646 \\u0623\\u0643\\u0628\\u0631 \\u0634\\u0631\\u0643\\u0627\\u062a \\u0627\\u0644\\u0633\\u0641\\u0631 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a \\u0641\\u064a \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645. \\u0641\\u064a \\u0639\\u0627\\u0645 2023\\u060c \\u062a\\u062c\\u0627\\u0648\\u0632 \\u0625\\u062c\\u0645\\u0627\\u0644\\u064a \\u0627\\u0644\\u062d\\u062c\\u0648\\u0632\\u0627\\u062a \\u0639\\u0628\\u0631 \\u0645\\u0646\\u0635\\u062a\\u0647\\u0627 150 \\u0645\\u0644\\u064a\\u0627\\u0631 \\u062f\\u0648\\u0644\\u0627\\u0631 \\u0623\\u0645\\u0631\\u064a\\u0643\\u064a\\u060c \\u0645\\u062d\\u062a\\u0644\\u0629\\u064b \\u0645\\u0627 \\u064a\\u0642\\u0627\\u0631\\u0628 46% \\u0645\\u0646 \\u062d\\u0635\\u0629 \\u0627\\u0644\\u0633\\u0648\\u0642 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645\\u064a\\u0629 \\u0644\\u0644\\u0633\\u0641\\u0631 \\u0639\\u0628\\u0631 \\u0627\\u0644\\u0625\\u0646\\u062a\\u0631\\u0646\\u062a\\u060c \\u0645\\u0645\\u0627 \\u064a\\u062c\\u0639\\u0644\\u0647\\u0627 \\u0641\\u064a \\u0645\\u0648\\u0642\\u0639 \\u0627\\u0644\\u0631\\u064a\\u0627\\u062f\\u0629&nbsp;. \\u0643\\u0645\\u0627 \\u062a\\u064f\\u0639\\u062f \\u0645\\u0648\\u0642\\u0639 Booking.com \\u0645\\u0646 \\u0628\\u064a\\u0646 \\u0623\\u0643\\u062b\\u0631 \\u0645\\u0648\\u0627\\u0642\\u0639 \\u0627\\u0644\\u0633\\u0641\\u0631 \\u0632\\u064a\\u0627\\u0631\\u0629\\u064b \\u0639\\u0644\\u0649 \\u0645\\u0633\\u062a\\u0648\\u0649 \\u0627\\u0644\\u0639\\u0627\\u0644\\u0645&nbsp;. \\u062a\\u0645\\u062a\\u0644\\u0643 \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629 \\u062b\\u0642\\u0627\\u0641\\u0629 \\u0642\\u0648\\u064a\\u0629 \\u0645\\u062f\\u0641\\u0648\\u0639\\u0629 \\u0628\\u0627\\u0644\\u0628\\u064a\\u0627\\u0646\\u0627\\u062a\\u060c \\u062d\\u064a\\u062b \\u062a\\u062c\\u0631\\u064a \\u0639\\u062f\\u062f\\u064b\\u0627 \\u0643\\u0628\\u064a\\u0631\\u064b\\u0627 \\u0645\\u0646 \\u0627\\u062e\\u062a\\u0628\\u0627\\u0631\\u0627\\u062a \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0627\\u0644\\u0645\\u0633\\u062a\\u062e\\u062f\\u0645 \\u064a\\u0648\\u0645\\u064a\\u064b\\u0627 \\u0644\\u062a\\u062d\\u0633\\u064a\\u0646 \\u062e\\u062f\\u0645\\u0627\\u062a\\u0647\\u0627 . \\u0641\\u064a \\u0627\\u0644\\u0633\\u0646\\u0648\\u0627\\u062a \\u0627\\u0644\\u0623\\u062e\\u064a\\u0631\\u0629\\u060c \\u062a\\u0628\\u0646\\u062a \\u0627\\u0644\\u0634\\u0631\\u0643\\u0629 \\u0628\\u0646\\u0634\\u0627\\u0637 \\u062a\\u0642\\u0646\\u064a\\u0627\\u062a \\u0627\\u0644\\u0630\\u0643\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0635\\u0637\\u0646\\u0627\\u0639\\u064a \\u0627\\u0644\\u062a\\u0648\\u0644\\u064a\\u062f\\u064a\\u060c \\u0648\\u0623\\u0637\\u0644\\u0642\\u062a \\u0645\\u064f\\u062e\\u0637\\u0650\\u0651\\u0637 \\u0631\\u062d\\u0644\\u0627\\u062a \\u0628\\u0627\\u0644\\u0630\\u0643\\u0627\\u0621 \\u0627\\u0644\\u0627\\u0635\\u0637\\u0646\\u0627\\u0639\\u064a\\u060c \\u064a\\u0633\\u0645\\u062d \\u0644\\u0644\\u0645\\u0633\\u0627\\u0641\\u0631\\u064a\\u0646 \\u0628\\u0627\\u0644\\u062d\\u0635\\u0648\\u0644 \\u0639\\u0644\\u0649 \\u0627\\u0642\\u062a\\u0631\\u0627\\u062d\\u0627\\u062a \\u0645\\u062e\\u0635\\u0635\\u0629 \\u0644\\u0644\\u0648\\u062c\\u0647\\u0627\\u062a \\u0648\\u0627\\u0644\\u0625\\u0642\\u0627\\u0645\\u0629 \\u0648\\u0627\\u0644\\u062e\\u0637\\u0637 \\u0627\\u0644\\u062a\\u0641\\u0635\\u064a\\u0644\\u064a\\u0629 \\u0645\\u0646 \\u062e\\u0644\\u0627\\u0644 \\u0645\\u062d\\u0627\\u062f\\u062b\\u0629 \\u0637\\u0628\\u064a\\u0639\\u064a\\u0629 . \\u0643\\u0645\\u0627 \\u064a\\u0636\\u0639 Booking.com \\u062a\\u062d\\u0633\\u064a\\u0646 \\u062a\\u062c\\u0631\\u0628\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0643\\u0647\\u062f\\u0641 \\u0645\\u0634\\u062a\\u0631\\u0643\\u060c \\u064a\\u0647\\u062f\\u0641 \\u0625\\u0644\\u0649 \\u062a\\u0639\\u0632\\u064a\\u0632 \\u0627\\u0644\\u0634\\u0639\\u0648\\u0631 \\u0628\\u0627\\u0644\\u0642\\u064a\\u0645\\u0629 \\u0627\\u0644\\u0630\\u0627\\u062a\\u064a\\u0629 \\u0644\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621<\\/p><p><\\/p>\",\"about_us_es\":\"<p>Booking.com es una de las mayores empresas de viajes online del mundo. En 2023, sus reservas totales superaron los 150 000 millones de d\\u00f3lares, lo que la sit\\u00faa como l\\u00edder con casi el 46 % de la cuota de mercado global de viajes online. Booking.com es uno de los sitios web de viajes m\\u00e1s visitados del mundo, con una s\\u00f3lida cultura basada en datos y que realiza diariamente exhaustivas pruebas de experiencia de usuario para optimizar sus servicios. En los \\u00faltimos a\\u00f1os, ha adoptado activamente la tecnolog\\u00eda de IA generativa, lanzando un planificador de viajes con IA que permite a los usuarios recibir sugerencias personalizadas de destinos, alojamiento e itinerarios mediante un di\\u00e1logo natural. Booking.com tambi\\u00e9n considera la mejora de la experiencia del cliente un objetivo com\\u00fan, con el fin de fortalecer su autoestima.<\\/p><p><\\/p>\",\"about_us_pt\":\"<p>A Booking.com \\u00e9 uma das maiores empresas de viagens online do mundo. Em 2023, as suas reservas totais ultrapassaram os 150 mil milh\\u00f5es de d\\u00f3lares, mantendo uma posi\\u00e7\\u00e3o de lideran\\u00e7a com quase 46% do mercado global de viagens online. A Booking.com \\u00e9 um dos sites de viagens mais visitados do mundo, ostentando uma forte cultura orientada por dados e realizando diariamente extensos testes de experi\\u00eancia do utilizador para otimizar os seus servi\\u00e7os. Nos \\u00faltimos anos, a empresa tem adotado ativamente a tecnologia de IA generativa, lan\\u00e7ando um planeador de viagens com IA que permite aos utilizadores receber sugest\\u00f5es personalizadas de destinos, alojamento e itiner\\u00e1rios atrav\\u00e9s de di\\u00e1logos naturais. A Booking.com considera tamb\\u00e9m a melhoria da experi\\u00eancia do cliente um objetivo comum, visando fortalecer a autoestima dos clientes.<\\/p><p><\\/p>\",\"about_us_nl\":\"<p>Booking.com is een van \'s werelds grootste online reisorganisaties. In 2023 bedroeg de totale boekingswaarde meer dan $ 150 miljard, waarmee het een leidende positie bekleedt met bijna 46% van het wereldwijde online reismarktaandeel. Booking.com is een van \'s werelds meest bezochte reiswebsites, met een sterke datagedreven cultuur en dagelijks uitgebreide gebruikerservaringstests om de dienstverlening te optimaliseren. De afgelopen jaren heeft het bedrijf actief gebruikgemaakt van generatieve AI-technologie en een AI-reisplanner gelanceerd waarmee gebruikers gepersonaliseerde suggesties voor bestemmingen, accommodaties en reisroutes kunnen ontvangen via een natuurlijke dialoog. Booking.com beschouwt het verbeteren van de klantervaring ook als een gezamenlijk doel, met als doel het gevoel van eigenwaarde van klanten te versterken.<\\/p><p><\\/p>\",\"about_us_fr\":\"<p>Booking.com est l\'une des plus grandes entreprises de voyages en ligne au monde. En 2023, son volume total de r\\u00e9servations a d\\u00e9pass\\u00e9 150 milliards de dollars, la pla\\u00e7ant en t\\u00eate du march\\u00e9 mondial du voyage en ligne avec pr\\u00e8s de 46 % de parts de march\\u00e9. Booking.com est l\'un des sites web de voyage les plus visit\\u00e9s au monde, et s\'appuie sur une forte culture ax\\u00e9e sur les donn\\u00e9es. L\'entreprise r\\u00e9alise quotidiennement des tests approfondis d\'exp\\u00e9rience utilisateur afin d\'optimiser ses services. Ces derni\\u00e8res ann\\u00e9es, elle a activement int\\u00e9gr\\u00e9 l\'intelligence artificielle g\\u00e9n\\u00e9rative, en lan\\u00e7ant un planificateur de voyage IA qui permet aux utilisateurs de recevoir des suggestions personnalis\\u00e9es de destinations, d\'h\\u00e9bergements et d\'itin\\u00e9raires gr\\u00e2ce \\u00e0 un dialogue naturel. Booking.com consid\\u00e8re \\u00e9galement l\'am\\u00e9lioration de l\'exp\\u00e9rience client comme un objectif commun, visant \\u00e0 renforcer le sentiment de satisfaction des clients.<\\/p><p><\\/p><p><\\/p>\",\"about_us_de\":\"<p>Booking.com ist eines der weltweit gr\\u00f6\\u00dften Online-Reiseunternehmen. 2023 \\u00fcberstiegen die Buchungen 150 Milliarden US-Dollar, womit das Unternehmen mit fast 46 % Marktanteil im globalen Online-Reisemarkt eine f\\u00fchrende Position einnimmt. Booking.com z\\u00e4hlt zu den meistbesuchten Reise-Websites weltweit und zeichnet sich durch eine starke datengetriebene Kultur aus. T\\u00e4glich werden umfangreiche Nutzertests durchgef\\u00fchrt, um die Services kontinuierlich zu optimieren. In den letzten Jahren hat das Unternehmen aktiv auf generative KI-Technologie gesetzt und einen KI-Reiseplaner eingef\\u00fchrt. Dieser erm\\u00f6glicht es Nutzern, personalisierte Vorschl\\u00e4ge f\\u00fcr Reiseziele, Unterk\\u00fcnfte und Reiserouten in nat\\u00fcrlicher Dialogform zu erhalten. Booking.com versteht die Verbesserung des Kundenerlebnisses als gemeinsames Ziel und m\\u00f6chte so das Selbstwertgef\\u00fchl seiner Kunden st\\u00e4rken.<\\/p><p><\\/p>\",\"register_en\":\"Congratulations o