d\\u0633\\u0627\\u0628 \\u0648\\u0627\\u062d\\u062f \\u0641\\u0642\\u0637.<\\/p><p><br><\\/p><p>3. \\u064a\\u064f\\u0645\\u0646\\u0639 \\u0645\\u0646\\u0639\\u064b\\u0627 \\u0628\\u0627\\u062a\\u064b\\u0627 \\u0625\\u0639\\u0627\\u062f\\u0629 \\u0631\\u0628\\u0637 \\u0646\\u0641\\u0633 \\u0627\\u0644\\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0628\\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0645\\u062e\\u062a\\u0644\\u0641\\u0629. \\u0641\\u064a \\u062d\\u0627\\u0644 \\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u0630\\u0644\\u0643\\u060c \\u0633\\u064a\\u062a\\u0645 \\u062a\\u062c\\u0645\\u064a\\u062f \\u0627\\u0644\\u062d\\u0633\\u0627\\u0628\\u0627\\u062a \\u0627\\u0644\\u062a\\u0627\\u0644\\u064a\\u0629.<\\/p><p><br><\\/p><p>4. \\u064a\\u064f\\u0631\\u062c\\u0649 \\u0639\\u062f\\u0645 \\u0627\\u0644\\u0625\\u0641\\u0635\\u0627\\u062d \\u0639\\u0646 \\u0643\\u0644\\u0645\\u0629 \\u0645\\u0631\\u0648\\u0631 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0648\\u0643\\u0644\\u0645\\u0629 \\u0645\\u0631\\u0648\\u0631 \\u0627\\u0644\\u0633\\u062d\\u0628 \\u0644\\u0623\\u064a \\u0634\\u062e\\u0635 \\u0622\\u062e\\u0631. \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u063a\\u064a\\u0631 \\u0645\\u0633\\u0624\\u0648\\u0644\\u0629 \\u0639\\u0646 \\u0623\\u064a \\u062e\\u0633\\u0627\\u0626\\u0631.<\\/p><p><br><\\/p><p>5. \\u064a\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062f \\u062c\\u0645\\u064a\\u0639 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0627\\u062a \\u0639\\u0634\\u0648\\u0627\\u0626\\u064a\\u064b\\u0627 \\u0628\\u0648\\u0627\\u0633\\u0637\\u0629 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645. \\u0628\\u0645\\u062c\\u0631\\u062f \\u062a\\u062d\\u062f\\u064a\\u062f\\u0647\\u0627\\u060c \\u064a\\u062a\\u0645 \\u0642\\u0628\\u0648\\u0644 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629 \\u0648\\u062a\\u062e\\u0635\\u064a\\u0635\\u0647\\u0627 \\u0645\\u0646 \\u0642\\u0650\\u0628\\u0644 \\u0627\\u0644\\u0646\\u0638\\u0627\\u0645. \\u064a\\u064f\\u0645\\u0646\\u0639 \\u0645\\u0646\\u0639\\u064b\\u0627 \\u0628\\u0627\\u062a\\u064b\\u0627 \\u0625\\u0644\\u063a\\u0627\\u0621 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629 \\u0623\\u0648 \\u0625\\u0644\\u063a\\u0627\\u0624\\u0647\\u0627 \\u0641\\u064a \\u062d\\u0627\\u0644 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0623\\u064a \\u062a\\u063a\\u064a\\u064a\\u0631\\u0627\\u062a. \\u064a\\u0645\\u0643\\u0646 \\u062a\\u062e\\u0635\\u064a\\u0635 \\u0627\\u0644\\u0628\\u0627\\u0642\\u0627\\u062a \\u0627\\u0644\\u0645\\u0645\\u064a\\u0632\\u0629 \\u0645\\u0646 0 \\u0625\\u0644\\u0649 3 \\u062e\\u0644\\u0627\\u0644 30 \\u0631\\u062d\\u0644\\u0629.<\\/p><p><br><\\/p><p>6. \\u0623\\u064a \\u0627\\u0633\\u062a\\u062e\\u062f\\u0627\\u0645 \\u063a\\u064a\\u0631 \\u0633\\u0644\\u064a\\u0645 \\u0633\\u064a\\u064f\\u0639\\u0631\\u0651\\u0636\\u0643 \\u0644\\u0644\\u0625\\u062c\\u0631\\u0627\\u0621\\u0627\\u062a \\u0627\\u0644\\u0642\\u0627\\u0646\\u0648\\u0646\\u064a\\u0629.<\\/p><p><br><\\/p><p>7. \\u064a\\u064f\\u0631\\u062c\\u0649 \\u062a\\u0623\\u0643\\u064a\\u062f \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u0625\\u064a\\u062f\\u0627\\u0639 \\u0644\\u062f\\u0649 \\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0642\\u0628\\u0644 \\u0625\\u062c\\u0631\\u0627\\u0621 \\u0627\\u0644\\u062a\\u062d\\u0648\\u064a\\u0644.<\\/p><p><br><\\/p><p>8. \\u0644\\u0646 \\u062a\\u064f\\u0639\\u0627\\u0644\\u062c \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u0627\\u0644\\u0625\\u064a\\u062f\\u0627\\u0639\\u0627\\u062a \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646\\u062a \\u0645\\u0639\\u0644\\u0648\\u0645\\u0627\\u062a \\u0627\\u0644\\u0625\\u064a\\u062f\\u0627\\u0639 \\u063a\\u064a\\u0631 \\u0635\\u062d\\u064a\\u062d\\u0629. \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629 \\u063a\\u064a\\u0631 \\u0645\\u0633\\u0624\\u0648\\u0644\\u0629 \\u0639\\u0646 \\u0623\\u064a \\u062e\\u0633\\u0627\\u0626\\u0631.<\\/p><p><br><\\/p><p>\\u0669. \\u0644\\u0646 \\u062a\\u062a\\u0645\\u0643\\u0646 \\u0645\\u0646 \\u0628\\u062f\\u0621 \\u0631\\u062d\\u0644\\u0629 \\u0625\\u0630\\u0627 \\u0643\\u0627\\u0646 \\u0631\\u0635\\u064a\\u062f\\u0643 \\u0623\\u0642\\u0644 \\u0645\\u0646 \\u0662\\u0660 \\u062f\\u0648\\u0644\\u0627\\u0631\\u064b\\u0627 \\u0623\\u0645\\u0631\\u064a\\u0643\\u064a\\u064b\\u0627. \\u0642\\u0628\\u0644 \\u0625\\u064a\\u062f\\u0627\\u0639 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u0644\\u060c \\u064a\\u062c\\u0628 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0639\\u0636\\u0627\\u0621 \\u0627\\u0644\\u062a\\u0623\\u0643\\u062f \\u0645\\u0646 \\u0623\\u0646 \\u0631\\u0635\\u064a\\u062f \\u062d\\u0633\\u0627\\u0628\\u0647\\u0645 \\u0662\\u0660 \\u062f\\u0648\\u0644\\u0627\\u0631\\u064b\\u0627 \\u0623\\u0645\\u0631\\u064a\\u0643\\u064a\\u064b\\u0627 \\u0644\\u0628\\u062f\\u0621 \\u0627\\u0644\\u0631\\u062d\\u0644\\u0629.<\\/p><p><br><\\/p><p>\\u0661\\u0660. \\u0628\\u0645\\u062c\\u0631\\u062f \\u0628\\u062f\\u0621 \\u0631\\u062d\\u0644\\u0629 \\u0627\\u0644\\u0639\\u0636\\u0648\\u060c \\u064a\\u062c\\u0628 \\u0639\\u0644\\u064a\\u0647 \\u0625\\u0643\\u0645\\u0627\\u0644\\u0647\\u0627 \\u062e\\u0644\\u0627\\u0644 \\u0662\\u0664 \\u0633\\u0627\\u0639\\u0629 \\u0645\\u0646 \\u062a\\u0627\\u0631\\u064a\\u062e \\u0627\\u0644\\u0628\\u062f\\u0621. \\u0641\\u064a \\u062d\\u0627\\u0644 \\u0639\\u062f\\u0645 \\u062a\\u0645\\u0643\\u0646\\u0647 \\u0645\\u0646 \\u0625\\u0643\\u0645\\u0627\\u0644\\u0647\\u0627 \\u062e\\u0644\\u0627\\u0644 \\u064a\\u0648\\u0645 \\u0648\\u0627\\u062d\\u062f\\u060c \\u064a\\u064f\\u0631\\u062c\\u0649 \\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u062e\\u062f\\u0645\\u0629 \\u0627\\u0644\\u0639\\u0645\\u0644\\u0627\\u0621 \\u0641\\u064a \\u0623\\u0642\\u0631\\u0628 \\u0648\\u0642\\u062a \\u0645\\u0645\\u0643\\u0646.<\\/p><p><br><\\/p><p>\\u0661\\u0661. \\u0642\\u062f \\u062a\\u0634\\u0645\\u0644 \\u0643\\u0644 \\u0628\\u0627\\u0642\\u0629 \\u0645\\u0645\\u064a\\u0632\\u0629 \\u0645\\u0646 \\u0661 \\u0625\\u0644\\u0649 \\u0663 \\u062a\\u062c\\u0627\\u0631 \\u0645\\u0646\\u062a\\u062c\\u0627\\u062a \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0646\\u0635\\u0629.<\\/p><p><br><\\/p><p>\\u0661\\u0662. \\u0633\\u064a\\u062d\\u0635\\u0644 \\u0627\\u0644\\u0623\\u0639\\u0636\\u0627\\u0621 \\u0627\\u0644\\u0630\\u064a\\u0646 \\u064a\\u0642\\u0648\\u0645\\u0648\\u0646 \\u0628\\u062a\\u0631\\u0642\\u064a\\u0629 \\u0645\\u0633\\u062a\\u0648\\u0649 \\u0639\\u0636\\u0648\\u064a\\u062a\\u0647\\u0645 \\u0639\\u0644\\u0649 \\u0628\\u0627\\u0642\\u0629 \\u0647\\u062f\\u0627\\u064a\\u0627 \\u0645\\u0645\\u064a\\u0632\\u0629.<\\/p><p><br><\\/p><p>\\u0661\\u0663. \\u064a\\u062c\\u0628 \\u0625\\u0643\\u0645\\u0627\\u0644 \\u0645\\u0647\\u0627\\u0645 \\u0627\\u0644\\u0639\\u0645\\u0644 \\u062e\\u0644\\u0627\\u0644 \\u0664\\u0668 \\u0633\\u0627\\u0639\\u0629\\u061b \\u0648\\u0625\\u0644\\u0627\\u060c \\u0633\\u064a\\u062a\\u0645 \\u062e\\u0635\\u0645 \\u062f\\u0631\\u062c\\u0629 \\u0627\\u0644\\u0627\\u0626\\u062a\\u0645\\u0627\\u0646 \\u0627\\u0644\\u062e\\u0627\\u0635\\u0629 \\u0628\\u0643.<\\/p><p><br><\\/p><p>\\u0639\\u0632\\u064a\\u0632\\u064a \\u0627\\u0644\\u0639\\u0636\\u0648\\u060c \\u064a\\u064f\\u0631\\u062c\\u0649 \\u0642\\u0631\\u0627\\u0621\\u0629 \\u0642\\u0648\\u0627\\u0639\\u062f\\u0646\\u0627 \\u0628\\u0639\\u0646\\u0627\\u064a\\u0629. \\u0634\\u0643\\u0631\\u064b\\u0627 \\u0644\\u062a\\u0639\\u0627\\u0648\\u0646\\u0643.<\\/p>\",\"register_es\":\"<p>T\\u00e9rminos y Condiciones<\\/p><p><br><\\/p><p>1. Todos los viajes deben completarse antes de su cancelaci\\u00f3n o reinicio.<\\/p><p><br><\\/p><p>2. Cada n\\u00famero de tel\\u00e9fono m\\u00f3vil solo puede registrar una cuenta.<\\/p><p><br><\\/p><p>3. Est\\u00e1 estrictamente prohibido vincular la misma informaci\\u00f3n a diferentes cuentas. En caso de detectarse, las cuentas correspondientes ser\\u00e1n bloqueadas.<\\/p><p><br><\\/p><p>4. No revele su contrase\\u00f1a de cuenta ni su contrase\\u00f1a de retiro a terceros. La plataforma no se responsabiliza de las p\\u00e9rdidas ocasionadas.<\\/p><p><br><\\/p><p>5. El sistema asigna los viajes aleatoriamente. Una vez asignado, el viaje queda aceptado y programado. Se proh\\u00edbe la cancelaci\\u00f3n o el abandono del viaje si se realizan cambios. Los paquetes Premium del 0 al 3 se pueden utilizar en un plazo de 30 viajes.<\\/p><p><br><\\/p><p>6. El uso indebido estar\\u00e1 sujeto a acciones legales.<\\/p><p><br><\\/p><p>7. Confirme la informaci\\u00f3n de dep\\u00f3sito con el servicio de atenci\\u00f3n al cliente antes de realizar cualquier pago.<\\/p><p><br><\\/p><p>8. La plataforma no procesar\\u00e1 los dep\\u00f3sitos si la informaci\\u00f3n proporcionada es incorrecta. La plataforma no se responsabiliza de los da\\u00f1os ocasionados.<\\/p><p><br><\\/p><p>9. No podr\\u00e1 iniciar un viaje si su saldo es inferior a 20 USDT. Antes de depositar fondos, los miembros deben asegurarse de que su saldo sea de 20 USDT para poder iniciar un viaje.<\\/p><p><br><\\/p><p>10. Una vez que un miembro inicia su viaje, debe completarlo dentro de las 24 horas posteriores a la fecha de inicio. Los miembros que no puedan completarlo en un d\\u00eda deben comunicarse con el servicio de atenci\\u00f3n al cliente lo antes posible.<\\/p><p><br><\\/p><p>11. Cada paquete premium puede incluir de 1 a 3 comercios de la plataforma.<\\/p><p><br><\\/p><p>12. Los miembros que actualicen su nivel de membres\\u00eda recibir\\u00e1n un paquete de regalo premium.<\\/p><p><br><\\/p><p>13. Las tareas deben completarse dentro de las 48 horas; de lo contrario, su puntaje crediticio se ver\\u00e1 afectado.<\\/p><p><br><\\/p><p>Estimado miembro, lea atentamente nuestras reglas. Gracias por su cooperaci\\u00f3n.<\\/p>\",\"register_pt\":\"<p>Termos e Condi\\u00e7\\u00f5es<\\/p><p><br><\\/p><p>1. Todas as viagens devem ser conclu\\u00eddas antes do cancelamento ou reposi\\u00e7\\u00e3o.<\\/p><p><br><\\/p><p>2.\\u00ba Cada n\\u00famero de telem\\u00f3vel s\\u00f3 pode registar uma conta.<\\/p><p><br><\\/p><p>3.\\u00ba \\u00c9 estritamente proibido ligar a mesma informa\\u00e7\\u00e3o a contas diferentes. Caso tal seja detetado, as contas subsequentes ser\\u00e3o bloqueadas.<\\/p><p><br><\\/p><p>4.\\u00ba N\\u00e3o divulgue a sua palavra-passe de conta e a palavra-passe de levantamento a terceiros. A plataforma n\\u00e3o se responsabiliza por eventuais perdas.<\\/p><p><br><\\/p><p>5. Todas as viagens s\\u00e3o atribu\\u00eddas aleatoriamente pelo sistema. Uma vez determinada, a viagem \\u00e9 aceite e atribu\\u00edda pelo sistema. O cancelamento ou abandono da viagem \\u00e9 estritamente proibido caso haja altera\\u00e7\\u00f5es. Os pacotes Premium de 0 a 3 podem ser alocados at\\u00e9 30 viagens.<\\/p><p><br><\\/p><p>6.\\u00ba Qualquer utiliza\\u00e7\\u00e3o indevida estar\\u00e1 sujeita a medidas legais.<\\/p><p><br><\\/p><p>7.\\u00ba Confirme as informa\\u00e7\\u00f5es de dep\\u00f3sito junto do servi\\u00e7o de apoio ao cliente antes de efetuar uma transfer\\u00eancia.<\\/p><p><br><\\/p><p>8. A plataforma n\\u00e3o processar\\u00e1 dep\\u00f3sitos se as informa\\u00e7\\u00f5es de dep\\u00f3sito estiverem incorretas. A plataforma n\\u00e3o se responsabiliza por quaisquer problemas da\\u00ed decorrentes.<\\/p><p><br><\\/p><p>9.\\u00ba N\\u00e3o poder\\u00e1 iniciar uma viagem se o seu saldo for inferior a 20 USDT. Antes de depositar fundos, os membros devem garantir que o saldo da conta \\u00e9 de 20 USDT para iniciar uma viagem.<\\/p><p><br><\\/p><p>10.\\u00ba Assim que um membro iniciar a sua viagem, dever\\u00e1 conclu\\u00ed-la no prazo de 24 horas a contar da data de in\\u00edcio. Os membros que n\\u00e3o conseguirem conclu\\u00ed-la num dia devem entrar em contacto com o servi\\u00e7o de apoio ao cliente o mais rapidamente poss\\u00edvel.<\\/p><p><br><\\/p><p>11.\\u00ba Cada pacote premium pode incluir 1 a 3 comerciantes de produtos da plataforma.<\\/p><p><br><\\/p><p>12.\\u00ba Os membros que atualizarem o seu n\\u00edvel de subscri\\u00e7\\u00e3o receber\\u00e3o um pacote de presentes premium.<\\/p><p><br><\\/p><p>13.As tarefas devem ser conclu\\u00eddas no prazo de 48 horas; caso contr\\u00e1rio, a sua pontua\\u00e7\\u00e3o de cr\\u00e9dito ser\\u00e1 reduzida.<\\/p><p><br><\\/p><p>Caro(a) membro, leia atentamente as nossas regras. Agradecemos a sua colabora\\u00e7\\u00e3o.<\\/p>\",\"register_nl\":\"<p>Algemene voorwaarden<\\/p><p><br><\\/p><p>1. Alle reizen moeten voltooid zijn voordat ze geannuleerd of gereset worden.<\\/p><p><br><\\/p><p>2. Elk mobiel telefoonnummer kan slechts \\u00e9\\u00e9n account registreren.<\\/p><p><br><\\/p><p>3. Het is ten strengste verboden om dezelfde informatie opnieuw aan verschillende accounts te koppelen. Bij ontdekking worden de volgende accounts geblokkeerd.<\\/p><p><br><\\/p><p>4. Geef uw accountwachtwoord en opnamewachtwoord niet door aan anderen. Het platform is niet aansprakelijk voor eventuele verliezen.<\\/p><p><br><\\/p><p>5. Alle reizen worden willekeurig toegewezen door het systeem. Zodra de reis is vastgesteld, is deze geaccepteerd en toegewezen door het systeem. Annulering of stopzetting van de reis is ten strengste verboden indien er wijzigingen worden aangebracht. Premiumpakketten 0 tot en met 3 kunnen binnen 30 reizen worden toegewezen.<\\/p><p><br><\\/p><p>6. Elk oneigenlijk gebruik kan aanleiding geven tot juridische stappen.<\\/p><p><br><\\/p><p>7. Controleer de stortingsgegevens bij de klantenservice voordat u een overschrijving doet.<\\/p><p><br><\\/p><p>8. Het platform verwerkt geen stortingen als de stortingsgegevens onjuist zijn. Het platform is hiervoor niet aansprakelijk.<\\/p><p><br><\\/p><p>9. Je kunt geen reis starten als je saldo lager is dan 20 USDT. Voordat je geld stort, moeten leden ervoor zorgen dat hun saldo 20 USDT bedraagt \\u200b\\u200bom een \\u200b\\u200breis te starten.<\\/p><p><br><\\/p><p>10. Zodra een lid aan zijn reis begint, moet hij\\/zij deze binnen 24 uur na de startdatum voltooien. Leden die de reis niet binnen \\u00e9\\u00e9n dag kunnen voltooien, dienen zo snel mogelijk contact op te nemen met de klantenservice.<\\/p><p><br><\\/p><p>11. Elk premiumpakket kan 1 tot 3 platformproductverkopers bevatten.<\\/p><p><br><\\/p><p>12. Leden die hun lidmaatschapsniveau verhogen, ontvangen een premium cadeaupakket.<\\/p><p><br><\\/p><p>13. Werktaken moeten binnen 48 uur worden voltooid, anders wordt je kredietscore in mindering gebracht.<\\/p><p><br><\\/p><p>Beste lid, lees onze regels aandachtig door. Bedankt voor je medewerking.<\\/p>\",\"register_fr\":\"<p>Conditions g\\u00e9n\\u00e9rales<\\/p><p><br><\\/p><p>1. Tout voyage doit \\u00eatre effectu\\u00e9 avant toute annulation ou r\\u00e9initialisation.<\\/p><p><br><\\/p><p>2. Un seul compte peut \\u00eatre cr\\u00e9\\u00e9 par num\\u00e9ro de t\\u00e9l\\u00e9phone mobile.<\\/p><p><br><\\/p><p>3. Il est strictement interdit d\'utiliser les m\\u00eames informations pour plusieurs comptes. Tout compte frauduleux sera bloqu\\u00e9.<\\/p><p><br><\\/p><p>4. Ne divulguez jamais vos mots de passe de compte et de retrait. La plateforme d\\u00e9cline toute responsabilit\\u00e9 en cas de perte.<\\/p><p><br><\\/p><p>5. Les voyages sont attribu\\u00e9s al\\u00e9atoirement par le syst\\u00e8me. Une fois l\'attribution effectu\\u00e9e, le voyage est valid\\u00e9. Toute annulation ou interruption est strictement interdite, m\\u00eame en cas de modification. Les forfaits Premium 0 \\u00e0 3 sont disponibles dans la limite de 30 voyages.<\\/p><p><br><\\/p><p>6. Toute utilisation abusive fera l\'objet de poursuites judiciaires.<\\/p><p><br><\\/p><p>7. Veuillez confirmer les informations de d\\u00e9p\\u00f4t aupr\\u00e8s du service client avant tout virement.<\\/p><p><br><\\/p><p>8. La plateforme refusera tout d\\u00e9p\\u00f4t si les informations fournies sont incorrectes. La plateforme d\\u00e9cline toute responsabilit\\u00e9.<\\/p><p><br><\\/p><p>9. Vous ne pourrez pas commencer un voyage si votre solde est inf\\u00e9rieur \\u00e0 20 USDT. Avant de d\\u00e9poser des fonds, les membres doivent s\'assurer que leur solde est d\'au moins 20 USDT pour pouvoir commencer un voyage.<\\/p><p><br><\\/p><p>10. Une fois leur voyage commenc\\u00e9, les membres doivent le terminer dans les 24 heures suivant la date de d\\u00e9but. Les membres qui ne peuvent pas le terminer dans ce d\\u00e9lai doivent contacter le service client d\\u00e8s que possible.<\\/p><p><br><\\/p><p>11. Chaque forfait premium peut inclure de 1 \\u00e0 3 marchands de produits de la plateforme.<\\/p><p><br><\\/p><p>12. Les membres qui passent \\u00e0 un niveau d\'abonnement sup\\u00e9rieur recevront un pack cadeau premium.<\\/p><p><br><\\/p><p>13. Les t\\u00e2ches doivent \\u00eatre termin\\u00e9es dans les 48 heures ; \\u00e0 d\\u00e9faut, votre score de cr\\u00e9dit sera r\\u00e9duit.<\\/p><p><br><\\/p><p>Cher membre, veuillez lire attentivement notre r\\u00e8glement. Merci de votre coop\\u00e9ration.<\\/p>\",\"register_de\":\"<p>Allgemeine Gesch\\u00e4ftsbedingungen<\\/p><p><br><\\/p><p>1. Alle Reisen m\\u00fcssen vor einer Stornierung oder einem Reset abgeschlossen sein.<\\/p><p><br><\\/p><p>2. Pro Mobiltelefonnummer kann nur ein Konto registriert werden.<\\/p><p><br><\\/p><p>3. Es ist strengstens verboten, dieselben Informationen f\\u00fcr verschiedene Konten zu verwenden. Bei Entdeckung werden die betroffenen Konten gesperrt.<\\/p><p><br><\\/p><p>4. Bitte geben Sie Ihr Kontopasswort und Ihr Auszahlungspasswort nicht an Dritte weiter. Die Plattform haftet nicht f\\u00fcr etwaige Verluste.<\\/p><p><br><\\/p><p>5. Alle Reisen werden vom System zuf\\u00e4llig zugewiesen. Sobald eine Reise zugewiesen wurde, gilt sie als best\\u00e4tigt. Stornierungen oder Abbr\\u00fcche sind bei \\u00c4nderungen strengstens untersagt. Premium-Pakete (0 bis 3) k\\u00f6nnen innerhalb von 30 Reisen zugeteilt werden.<\\/p><p><br><\\/p><p>6. Jeglicher Missbrauch wird rechtlich verfolgt.<\\/p><p><br><\\/p><p>7. Bitte best\\u00e4tigen Sie die Einzahlungsinformationen vor der \\u00dcberweisung mit dem Kundenservice.<\\/p><p><br><\\/p><p>8. Die Plattform bearbeitet keine Einzahlungen, wenn die Einzahlungsinformationen fehlerhaft sind. Die Plattform \\u00fcbernimmt keine Haftung.<\\/p><p><br><\\/p><p>9. Sie k\\u00f6nnen keine Reise antreten, wenn Ihr Guthaben unter 20 USDT liegt. Vor der Einzahlung m\\u00fcssen Mitglieder sicherstellen, dass ihr Kontostand mindestens 20 USDT betr\\u00e4gt, um eine Reise zu starten.<\\/p><p><br><\\/p><p>10. Sobald ein Mitglied seine Reise beginnt, muss diese innerhalb von 24 Stunden nach dem Startdatum abgeschlossen sein. Mitglieder, die die Reise nicht innerhalb eines Tages abschlie\\u00dfen k\\u00f6nnen, sollten sich umgehend an den Kundenservice wenden.<\\/p><p><br><\\/p><p>11. Jedes Premium-Paket kann 1 bis 3 Produkte von Plattformanbietern enthalten.<\\/p><p><br><\\/p><p>12. Mitglieder, die ihre Mitgliedschaft upgraden, erhalten ein Premium-Geschenkpaket.<\\/p><p><br><\\/p><p>13. Arbeitsaufgaben m\\u00fcssen innerhalb von 48 Stunden erledigt sein; andernfalls wird Ihre Kreditw\\u00fcrdigkeit beeintr\\u00e4chtigt.<\\/p><p><br><\\/p><p>Liebes Mitglied, bitte lesen Sie unsere Regeln sorgf\\u00e4ltig durch. Vielen Dank f\\u00fcr Ihre Mitarbeit.<\\/p>\"}',1763369759),(6,'公告','{\"tips_zh\":\"<p>\\u6b61\\u8fce\\u60a8\\u7684\\u5149\\u81e8\\uff0c\\u6211\\u5011\\u5c07\\u7aed\\u8aa0\\u70ba\\u6bcf\\u4f4d\\u4f7f\\u7528\\u8005\\u670d\\u52d9\\uff0c\\u611f\\u8b1d\\u60a8\\u5c0d\\uff08APPLOVIN\\uff09\\u7684\\u652f\\u6301\\u8207\\u4fe1\\u4efb<\\/p>\",\"tips_en\":\"<p>\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8<\\/p>\",\"tips_hy\":\"<p>\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8\\ud55c\\uad6d\\uc5b4 \\ud14c\\uc2a4\\ud2b8<\\/p>\",\"tips_jp\":\"jp\"}',1696663225);
